 /** Mark only a bank-confirmed FinTS result as submitted; never books the invoice. */
 public function markFintsSubmitted(string $id,int $version,string $reference,int $attempt=0):void{$reference=trim($reference);if($reference===''||mb_strlen($reference)>200)throw new DomainException('Bankbestätigung prüfen.');$this->tx(function()use($id,$version,$reference,$attempt){$a=$this->access();$this->office($this->actor);$transport=$this->transport($id);if($transport['pending']??false){if($attempt<1||(int)$transport['event']['sequence']!==$attempt||$transport['event']['actor_id']!==$a['id']||(int)$transport['event']['object_version']!==$version)throw new DomainException('Genau den aktuellen offenen FinTS-Ausgang erneut prüfen.',409);}elseif($attempt!==0)throw new DomainException('Genau den aktuellen offenen FinTS-Ausgang erneut prüfen.',409);$r=$this->get($id);if($r['state']!=='approved'||(int)$r['version']!==$version)throw new DomainException('Überweisungsauftrag wurde bereits verarbeitet oder geändert.');if(!($transport['pending']??false)){$this->current($r);$this->office((string)$r['approved_by']);}$this->q("UPDATE finance_transfer_orders SET state='submitted',bank_reference=?,version=version+1 WHERE club_id=? AND id=?",[$reference,$a['club_id'],$id]);$this->audit('finance.transfer.fints_submitted',$id,$version+1);});}
 public function approve(string $id,int $version):void{$this->tx(function()use($id,$version){$a=$this->access();$r=$this->get($id);if($r['state']!=='prepared'||(int)$r['version']!==$version)throw new DomainException('Unveränderten vorbereiteten Überweisungsauftrag auswählen.');$this->assertNoPendingOrder($r['entry_id'],$id);$this->current($r);$o=$this->office($this->actor);(new InvoiceApprovals($this->db,$this->actor))->assertApproved($r['entry_id'],true);$this->q("UPDATE finance_transfer_orders SET state='approved',approved_by=?,approved_at=?,office_version=?,version=version+1 WHERE club_id=? AND id=?",[$a['id'],gmdate('c'),$o['version'],$a['club_id'],$id]);$this->audit('finance.transfer.approved',$id,$version+1);$this->audit('finance.transfer.tracking_ready',$id,$version+1);});}
 public function export(string $id,int $version):string{return $this->tx(function()use($id,$version){$a=$this->access();$this->noPendingTransport($id);$this->office($this->actor);$r=$this->get($id);if(!in_array($r['state'],['approved','exported'],true)||(int)$r['version']!==$version)throw new DomainException('Zuerst den aktuellen Zahlungsauftrag freigeben.');(new InvoiceApprovals($this->db,$this->actor))->assertApproved($r['entry_id'],true);$this->assertNoPendingOrder($r['entry_id'],$id);$s=$this->current($r);$o=$this->office((string)$r['approved_by']);if((int)$o['version']!==(int)$r['office_version'])throw new DomainException('Freigabeamt geändert. Auftrag neu prüfen.');if($r['state']==='approved'){$this->q("UPDATE finance_transfer_orders SET state='exported',exported_at=?,version=version+1 WHERE club_id=? AND id=?",[gmdate('c'),$a['club_id'],$id]);$this->audit('finance.transfer.exported',$id,$version+1);}return $s['xml'];});}
 public function submitted(string $id,int $version,string $reference):void{$reference=trim($reference);if($reference===''||mb_strlen($reference)>200)throw new DomainException('Bankbestätigung oder Auftragsnummer eingeben.');$this->tx(function()use($id,$version,$reference){$a=$this->access();$this->office($this->actor);$r=$this->get($id);if($r['state']!=='exported'||(int)$r['version']!==$version)throw new DomainException('Unveränderten exportierten Auftrag auswählen.');$this->q("UPDATE finance_transfer_orders SET state='submitted',bank_reference=?,version=version+1 WHERE club_id=? AND id=?",[$reference,$a['club_id'],$id]);$this->audit('finance.transfer.externally_submitted',$id,$version+1);});}
 public function cancel(string $id,int $version):void{$this->tx(function()use($id,$version){$a=$this->access();$this->noPendingTransport($id);$r=$this->get($id);if(!in_array($r['state'],['prepared','approved'],true)||(int)$r['version']!==$version)throw new DomainException('Exportierte Überweisungen zuerst bei der Bank klären.');$this->q("UPDATE finance_transfer_orders SET state='cancelled',version=version+1 WHERE club_id=? AND id=?",[$a['club_id'],$id]);$this->audit('finance.transfer.cancelled',$id,$version+1);});}
 public static function xml(array $s):string
 {
  $mode=PaymentRules::transferMode($s['transfer_mode']??'standard');$d=new DOMDocument('1.0','UTF-8');$d->formatOutput=true;$ns='urn:iso:std:iso:20022:tech:xsd:pain.001.001.09';$root=$d->createElementNS($ns,'Document');$d->appendChild($root);$add=static function($parent,string $name,?string $value=null)use($d,$ns){$n=$d->createElementNS($ns,$name);if($value!==null)$n->appendChild($d->createTextNode($value));$parent->appendChild($n);return $n;};$init=$add($root,'CstmrCdtTrfInitn');$h=$add($init,'GrpHdr');$add($h,'MsgId','KH'.$s['id']);$add($h,'CreDtTm',$s['created_at']);$add($h,'NbOfTxs','1');$add($h,'CtrlSum',Finance::decimal($s['total_cents']));$add($add($h,'InitgPty'),'Nm',mb_substr($s['source']['name'],0,70));$p=$add($init,'PmtInf');$add($p,'PmtInfId','KH'.$s['id']);$add($p,'PmtMtd','TRF');$add($p,'BtchBookg','false');$add($p,'NbOfTxs','1');$add($p,'CtrlSum',Finance::decimal($s['total_cents']));$type=$add($p,'PmtTpInf');$lvl=$add($type,'SvcLvl');$add($lvl,'Cd','SEPA');if($mode==='instant')$add($add($type,'LclInstrm'),'Cd','INST');$req=$add($p,'ReqdExctnDt');$add($req,'Dt',$s['execution_date']);$add($add($p,'Dbtr'),'Nm',mb_substr($s['source']['name'],0,70));$sourceAcct=$add($add($p,'DbtrAcct'),'Id');$add($sourceAcct,'IBAN',$s['source']['iban']);$agent=$add($add($p,'DbtrAgt'),'FinInstnId');if($s['source']['bic']!=='')$add($agent,'BICFI',$s['source']['bic']);else $add($add($agent,'Othr'),'Id','NOTPROVIDED');$add($p,'ChrgBr','SLEV');$tx=$add($p,'CdtTrfTxInf');$add($add($tx,'PmtId'),'EndToEndId','KH'.substr($s['id'],0,24).'-1');$amt=$add($add($tx,'Amt'),'InstdAmt',Finance::decimal($s['total_cents']));$amt->setAttribute('Ccy','EUR');if($s['recipient']['bic']!=='')$add($add($add($tx,'CdtrAgt'),'FinInstnId'),'BICFI',$s['recipient']['bic']);$add($add($tx,'Cdtr'),'Nm',mb_substr($s['recipient']['name'],0,70));$add($add($add($tx,'CdtrAcct'),'Id'),'IBAN',$s['recipient']['iban']);$add($add($tx,'RmtInf'),'Ustrd',mb_substr($s['purpose'],0,140));$xml=$d->saveXML();if($xml===false||!$d->documentElement||$d->documentElement->localName!=='Document')throw new DomainException('Überweisungsdatei konnte nicht erstellt werden.');$old=libxml_use_internal_errors(true);try{if(!$d->schemaValidate(dirname(dirname(__DIR__, 2),2).'/banking/schemas/pain.001.001.09_GBIC_5.xsd'))throw new DomainException('Überweisungsdatei entspricht nicht dem SEPA-Format. Angaben prüfen.');}finally{libxml_clear_errors();libxml_use_internal_errors($old);}return $xml;
 }
